-- =====================================================================================
--  RAPIDO RIDE-HAILING DATABASE  (synthetic data)            Target: MySQL 8.0+ / Workbench
-- =====================================================================================
DROP DATABASE IF EXISTS rapido_db;
CREATE DATABASE rapido_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rapido_db;

-- ---------- Reference / lookup tables ----------
CREATE TABLE payment_methods (
    payment_method_id   INT          NOT NULL AUTO_INCREMENT,
    method_name         VARCHAR(20)  NOT NULL,
    is_digital          TINYINT(1)   NOT NULL,
    PRIMARY KEY (payment_method_id),
    UNIQUE KEY uq_payment_method_name (method_name)
) ENGINE=InnoDB;

CREATE TABLE cities (
    city_id             INT          NOT NULL AUTO_INCREMENT,
    city_name           VARCHAR(50)  NOT NULL,
    state               VARCHAR(50)  NOT NULL,
    city_tier           ENUM('Tier 1','Tier 2') NOT NULL,
    latitude            DECIMAL(9,6) NOT NULL,
    longitude           DECIMAL(9,6) NOT NULL,
    fare_multiplier     DECIMAL(3,2) NOT NULL DEFAULT 1.00,
    PRIMARY KEY (city_id),
    UNIQUE KEY uq_city_name (city_name)
) ENGINE=InnoDB;

CREATE TABLE vehicle_types (
    vehicle_type_id     INT          NOT NULL AUTO_INCREMENT,
    type_name           VARCHAR(20)  NOT NULL,
    base_fare           DECIMAL(6,2) NOT NULL,
    per_km_rate         DECIMAL(6,2) NOT NULL,
    per_min_rate        DECIMAL(6,2) NOT NULL,
    min_fare            DECIMAL(6,2) NOT NULL,
    seating_capacity    TINYINT      NOT NULL,
    PRIMARY KEY (vehicle_type_id),
    UNIQUE KEY uq_vehicle_type_name (type_name)
) ENGINE=InnoDB;

CREATE TABLE localities (
    locality_id         INT          NOT NULL AUTO_INCREMENT,
    city_id             INT          NOT NULL,
    locality_name       VARCHAR(80)  NOT NULL,
    zone_type           ENUM('Residential','Commercial','IT Hub','Transit Hub','Airport','Market/Mall','Education') NOT NULL,
    latitude            DECIMAL(9,6) NOT NULL,
    longitude           DECIMAL(9,6) NOT NULL,
    PRIMARY KEY (locality_id),
    UNIQUE KEY uq_city_locality (city_id, locality_name),
    CONSTRAINT fk_locality_city FOREIGN KEY (city_id) REFERENCES cities (city_id)
) ENGINE=InnoDB;

CREATE TABLE cancellation_reasons (
    reason_id           INT          NOT NULL AUTO_INCREMENT,
    reason_text         VARCHAR(100) NOT NULL,
    cancelled_by        ENUM('Customer','Captain','System') NOT NULL,
    PRIMARY KEY (reason_id)
) ENGINE=InnoDB;

-- ---------- Master tables ----------
CREATE TABLE customers (
    customer_id                 INT          NOT NULL AUTO_INCREMENT,
    full_name                   VARCHAR(100) NOT NULL,
    gender                      ENUM('Male','Female','Other') NOT NULL,
    phone                       CHAR(10)     NOT NULL,
    email                       VARCHAR(120) NULL,
    city_id                     INT          NOT NULL,
    signup_date                 DATE         NOT NULL,
    app_platform                ENUM('Android','iOS') NOT NULL,
    preferred_payment_method_id INT          NOT NULL,
    total_rides_completed       INT          NOT NULL DEFAULT 0,
    avg_rating                  DECIMAL(3,2) NULL COMMENT 'average rating given to this customer by captains',
    PRIMARY KEY (customer_id),
    UNIQUE KEY uq_customer_phone (phone),
    KEY idx_customer_city (city_id),
    CONSTRAINT fk_customer_city FOREIGN KEY (city_id) REFERENCES cities (city_id),
    CONSTRAINT fk_customer_pay  FOREIGN KEY (preferred_payment_method_id) REFERENCES payment_methods (payment_method_id)
) ENGINE=InnoDB;

CREATE TABLE captains (
    captain_id              INT          NOT NULL AUTO_INCREMENT,
    full_name               VARCHAR(100) NOT NULL,
    gender                  ENUM('Male','Female') NOT NULL,
    phone                   CHAR(10)     NOT NULL,
    city_id                 INT          NOT NULL,
    vehicle_type_id         INT          NOT NULL,
    vehicle_number          VARCHAR(12)  NOT NULL,
    vehicle_model           VARCHAR(50)  NOT NULL,
    fuel_type               ENUM('Petrol','CNG','Diesel','Electric') NOT NULL,
    license_number          VARCHAR(20)  NOT NULL,
    join_date               DATE         NOT NULL,
    kyc_status              ENUM('Verified','Pending','Rejected') NOT NULL,
    status                  ENUM('Active','Inactive','Suspended') NOT NULL,
    total_rides_completed   INT          NOT NULL DEFAULT 0,
    avg_rating              DECIMAL(3,2) NULL COMMENT 'average rating given to this captain by customers',
    PRIMARY KEY (captain_id),
    UNIQUE KEY uq_captain_phone (phone),
    UNIQUE KEY uq_captain_vehicle_no (vehicle_number),
    KEY idx_captain_city_vehicle (city_id, vehicle_type_id),
    CONSTRAINT fk_captain_city    FOREIGN KEY (city_id) REFERENCES cities (city_id),
    CONSTRAINT fk_captain_vehicle FOREIGN KEY (vehicle_type_id) REFERENCES vehicle_types (vehicle_type_id)
) ENGINE=InnoDB;

-- ---------- Transaction tables ----------
CREATE TABLE rides (
    ride_id                 INT           NOT NULL AUTO_INCREMENT,
    ride_code               VARCHAR(20)   NOT NULL,
    customer_id             INT           NOT NULL,
    captain_id              INT           NULL COMMENT 'NULL when cancelled before a captain was assigned',
    city_id                 INT           NOT NULL,
    vehicle_type_id         INT           NOT NULL,
    pickup_locality_id      INT           NOT NULL,
    drop_locality_id        INT           NOT NULL,
    pickup_address          VARCHAR(150)  NOT NULL,
    drop_address            VARCHAR(150)  NOT NULL,
    pickup_lat              DECIMAL(9,6)  NOT NULL,
    pickup_lng              DECIMAL(9,6)  NOT NULL,
    drop_lat                DECIMAL(9,6)  NOT NULL,
    drop_lng                DECIMAL(9,6)  NOT NULL,
    ride_type               ENUM('Normal','Scheduled') NOT NULL,
    requested_at            DATETIME      NOT NULL,
    scheduled_for           DATETIME      NULL,
    captain_assigned_at     DATETIME      NULL,
    ride_start_time         DATETIME      NULL,
    ride_end_time           DATETIME      NULL,
    ride_status             ENUM('Completed','Cancelled','Ongoing') NOT NULL,
    distance_km             DECIMAL(6,2)  NOT NULL COMMENT 'actual km for completed rides, estimated route km otherwise',
    duration_min            SMALLINT UNSIGNED NULL COMMENT 'only for completed rides',
    surge_multiplier        DECIMAL(3,2)  NOT NULL DEFAULT 1.00,
    estimated_fare          DECIMAL(8,2)  NOT NULL,
    fare_amount             DECIMAL(8,2)  NULL COMMENT 'final fare (incl. surge, before tax/discount) - completed rides only',
    PRIMARY KEY (ride_id),
    UNIQUE KEY uq_ride_code (ride_code),
    KEY idx_ride_customer (customer_id),
    KEY idx_ride_captain (captain_id),
    KEY idx_ride_city_vehicle (city_id, vehicle_type_id),
    KEY idx_ride_pickup (pickup_locality_id),
    KEY idx_ride_drop (drop_locality_id),
    KEY idx_ride_requested (requested_at),
    KEY idx_ride_status (ride_status),
    CONSTRAINT fk_ride_customer FOREIGN KEY (customer_id)        REFERENCES customers (customer_id),
    CONSTRAINT fk_ride_captain  FOREIGN KEY (captain_id)         REFERENCES captains (captain_id),
    CONSTRAINT fk_ride_city     FOREIGN KEY (city_id)            REFERENCES cities (city_id),
    CONSTRAINT fk_ride_vehicle  FOREIGN KEY (vehicle_type_id)    REFERENCES vehicle_types (vehicle_type_id),
    CONSTRAINT fk_ride_pickup   FOREIGN KEY (pickup_locality_id) REFERENCES localities (locality_id),
    CONSTRAINT fk_ride_drop     FOREIGN KEY (drop_locality_id)   REFERENCES localities (locality_id),
    CONSTRAINT chk_surge CHECK (surge_multiplier >= 1.00),
    CONSTRAINT chk_distance CHECK (distance_km > 0)
) ENGINE=InnoDB;

CREATE TABLE ride_cancellations (
    cancellation_id     INT           NOT NULL AUTO_INCREMENT,
    ride_id             INT           NOT NULL,
    reason_id           INT           NOT NULL,
    cancelled_at        DATETIME      NOT NULL,
    cancellation_fee    DECIMAL(6,2)  NOT NULL DEFAULT 0.00,
    PRIMARY KEY (cancellation_id),
    UNIQUE KEY uq_cancel_ride (ride_id),
    KEY idx_cancel_reason (reason_id),
    CONSTRAINT fk_cancel_ride   FOREIGN KEY (ride_id)   REFERENCES rides (ride_id),
    CONSTRAINT fk_cancel_reason FOREIGN KEY (reason_id) REFERENCES cancellation_reasons (reason_id)
) ENGINE=InnoDB;

CREATE TABLE payments (
    payment_id          INT           NOT NULL AUTO_INCREMENT,
    ride_id             INT           NOT NULL,
    payment_method_id   INT           NOT NULL,
    payment_provider    VARCHAR(30)   NULL COMMENT 'PhonePe, Google Pay, Visa Debit, Rapido Wallet ... NULL for cash',
    attempt_no          TINYINT       NOT NULL DEFAULT 1,
    base_amount         DECIMAL(8,2)  NOT NULL COMMENT 'ride fare, or cancellation fee',
    discount_amount     DECIMAL(8,2)  NOT NULL DEFAULT 0.00,
    tax_amount          DECIMAL(8,2)  NOT NULL DEFAULT 0.00,
    tip_amount          DECIMAL(8,2)  NOT NULL DEFAULT 0.00,
    total_amount        DECIMAL(8,2)  NOT NULL,
    coupon_code         VARCHAR(20)   NULL,
    payment_status      ENUM('Success','Failed','Pending','Refunded') NOT NULL,
    transaction_ref     VARCHAR(30)   NULL,
    payment_time        DATETIME      NULL,
    PRIMARY KEY (payment_id),
    KEY idx_pay_ride (ride_id),
    KEY idx_pay_method (payment_method_id),
    KEY idx_pay_status (payment_status),
    CONSTRAINT fk_pay_ride   FOREIGN KEY (ride_id)           REFERENCES rides (ride_id),
    CONSTRAINT fk_pay_method FOREIGN KEY (payment_method_id) REFERENCES payment_methods (payment_method_id),
    CONSTRAINT chk_total CHECK (total_amount >= 0)
) ENGINE=InnoDB;

CREATE TABLE ratings_reviews (
    review_id           INT           NOT NULL AUTO_INCREMENT,
    ride_id             INT           NOT NULL,
    customer_id         INT           NOT NULL,
    captain_id          INT           NOT NULL,
    customer_rating     TINYINT       NOT NULL COMMENT 'rating given by customer to captain (1-5)',
    review_text         VARCHAR(255)  NULL,
    review_sentiment    ENUM('Positive','Neutral','Negative') NOT NULL,
    captain_rating      TINYINT       NULL COMMENT 'rating given by captain to customer (1-5)',
    captain_feedback    VARCHAR(255)  NULL,
    rated_at            DATETIME      NOT NULL,
    PRIMARY KEY (review_id),
    UNIQUE KEY uq_review_ride (ride_id),
    KEY idx_review_customer (customer_id),
    KEY idx_review_captain (captain_id),
    CONSTRAINT fk_review_ride     FOREIGN KEY (ride_id)     REFERENCES rides (ride_id),
    CONSTRAINT fk_review_customer FOREIGN KEY (customer_id) REFERENCES customers (customer_id),
    CONSTRAINT fk_review_captain  FOREIGN KEY (captain_id)  REFERENCES captains (captain_id),
    CONSTRAINT chk_cust_rating CHECK (customer_rating BETWEEN 1 AND 5),
    CONSTRAINT chk_cap_rating  CHECK (captain_rating IS NULL OR captain_rating BETWEEN 1 AND 5)
) ENGINE=InnoDB;

-- ---------- Convenience view ----------
CREATE OR REPLACE VIEW vw_ride_details AS
SELECT  r.ride_id, r.ride_code, r.ride_status, r.ride_type, r.requested_at, r.ride_start_time, r.ride_end_time,
        c.city_name, vt.type_name AS vehicle_type,
        pl.locality_name AS pickup_locality, dl.locality_name AS drop_locality,
        r.distance_km, r.duration_min, r.surge_multiplier, r.estimated_fare, r.fare_amount,
        cu.customer_id, cu.full_name AS customer_name,
        ca.captain_id, ca.full_name AS captain_name,
        cr.reason_text AS cancellation_reason, cr.cancelled_by,
        rr.customer_rating
FROM rides r
JOIN cities c              ON c.city_id = r.city_id
JOIN vehicle_types vt      ON vt.vehicle_type_id = r.vehicle_type_id
JOIN localities pl         ON pl.locality_id = r.pickup_locality_id
JOIN localities dl         ON dl.locality_id = r.drop_locality_id
JOIN customers cu          ON cu.customer_id = r.customer_id
LEFT JOIN captains ca      ON ca.captain_id = r.captain_id
LEFT JOIN ride_cancellations rc ON rc.ride_id = r.ride_id
LEFT JOIN cancellation_reasons cr ON cr.reason_id = rc.reason_id
LEFT JOIN ratings_reviews rr ON rr.ride_id = r.ride_id;

